import{_ as n,C as c,o as i,c as s,j as d,a as o,E as e,ah as r}from"./chunks/framework.BpF7DVZ1.js";const P=JSON.parse('{"title":"工具调用","description":"","frontmatter":{},"headers":[],"relativePath":"components/tool-call.md","filePath":"components/tool-call.md","lastUpdated":1788644314000}'),h={name:"components/tool-call.md"},p={id:"工具调用",tabindex:"-1"};function u(b,t,g,x,m,f){const l=c("Badge"),a=c("XhDemo");return i(),s("div",null,[d("h1",p,[t[0]||(t[0]=o("工具调用 ",-1)),e(l,{type:"info",text:"tool-call"}),t[1]||(t[1]=o()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#工具调用","aria-label":'Permalink to "工具调用 <Badge type="info" text="tool-call" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一次工具调用的卡片：阶段、参数与结果，跑起来自动展开、结束自动收起，用户动手过一次就不再自动。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>Agent 界面里展示「它正在做什么」：查了什么、传了什么参数、拿回了什么。</li><li>一次调用要先经人批准才能执行。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>展示的是「思考过程」而不是一次调用：用<a href="./reasoning">思考过程</a>，两者共用同一台机器但正文形态不同。</li><li>只想要一个状态色块：用<a href="./badge">徽章</a>，配 <code>toneOfToolCallPhase(phase)</code> 取语气。</li><li>多次调用要一次只展开一张：外面套<a href="./accordion">手风琴</a>，每格里装一张。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>五档阶段：参数在传、参数齐了、等人批准、已完成、出错了。 <strong>「等人批准」不是「在跑」</strong>——协议层的审批只改审批状态、不改工具状态， 没有这一档的话等人的调用会被当成在跑。</li><li><strong>自动开合的锁存靠转移的放置位置，不靠一个布尔位</strong>：用户点过一次之后， 阶段变化在结构上就够不着任何转移，自动开合永久停用。</li><li>审批闸门常驻在开关与详情之间，不会被折叠藏起来。</li><li>收起走 <code>hidden</code> + <code>inert</code>：退场动画播完之前内容还在渲染，<code>inert</code> 把这段窗口挡在读屏与 Tab 序之外。</li><li>开关那一行留了摘要位与耗时位：详情收起时也看得见「查了什么」与「跑了多久」。</li><li>耗时由宿主给两个时刻，<code>toolCallDuration(startTime, endTime)</code> 折出毫秒数； <strong>组件自己不读时钟也不起定时器</strong>，秒数要跳就由宿主驱动。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="五档阶段" tabindex="-1">五档阶段 <a class="header-anchor" href="#五档阶段" aria-label="Permalink to &quot;五档阶段&quot;">​</a></h3><p>等人批准不是在跑：闸门常驻在开关与详情之间，不会被折叠藏起来</p>',10)),e(a,{src:"tool-call/01-phases"}),t[4]||(t[4]=d("h3",{id:"自动开合与锁存",tabindex:"-1"},[o("自动开合与锁存 "),d("a",{class:"header-anchor",href:"#自动开合与锁存","aria-label":'Permalink to "自动开合与锁存"'},"​")],-1)),t[5]||(t[5]=d("p",null,"跑起来自动展开、结束自动收起；你手动开合过一次之后，阶段怎么变都不再自动",-1)),e(a,{src:"tool-call/02-auto-disclosure"}),t[6]||(t[6]=d("h3",{id:"摘要与耗时",tabindex:"-1"},[o("摘要与耗时 "),d("a",{class:"header-anchor",href:"#摘要与耗时","aria-label":'Permalink to "摘要与耗时"'},"​")],-1)),t[7]||(t[7]=d("p",null,"详情收起时也看得见查了什么、跑了多久；两个时刻由宿主给，组件自己不读时钟",-1)),e(a,{src:"tool-call/03-summary-duration"}),t[8]||(t[8]=d("h3",{id:"多次调用分组",tabindex:"-1"},[o("多次调用分组 "),d("a",{class:"header-anchor",href:"#多次调用分组","aria-label":'Permalink to "多次调用分组"'},"​")],-1)),t[9]||(t[9]=d("p",null,"外面套一层手风琴当分组头：计数用等宽数位，整组开合归手风琴，卡片各管各的",-1)),e(a,{src:"tool-call/04-grouped"}),t[10]||(t[10]=d("h3",{id:"形态、语气与尺寸",tabindex:"-1"},[o("形态、语气与尺寸 "),d("a",{class:"header-anchor",href:"#形态、语气与尺寸","aria-label":'Permalink to "形态、语气与尺寸"'},"​")],-1)),t[11]||(t[11]=d("p",null,"三轴只改这块壳怎么与正文分开，阶段与展开逻辑不受影响",-1)),e(a,{src:"tool-call/05-variant-tone-size"}),t[12]||(t[12]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tool-call&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhToolCallApproval</code> <code>XhToolCallContent</code> <code>XhToolCallDuration</code> <code>XhToolCallError</code> <code>XhToolCallIndicator</code> <code>XhToolCallInput</code> <code>XhToolCallLabel</code> <code>XhToolCallOutput</code> <code>XhToolCallRoot</code> <code>XhToolCallStatus</code> <code>XhToolCallSummary</code> <code>XhToolCallTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useToolCall</code></td></tr><tr><td>状态机</td><td><code>toolCallMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tool-call.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tool-call&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <code>indicator</code> · <code>label</code> · <code>summary</code> · <code>status</code> · <code>duration</code> · <code>approval</code> · <strong><code>content</code></strong> · <code>input</code> · <code>output</code> · <code>error</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>running</code></td><td><code>boolean</code></td><td></td><td>这次调用正在跑。适配器用 isToolCallRunning(phase) 折出来，作者只写 phase。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>autoDisclosure</code></td><td><code>boolean</code></td><td></td><td>跑起来自动展开、结束自动收起，默认开；用户手动开合过一次即永久停用。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: ToolCallOpenChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>endTime</code></td><td><code>number</code></td><td></td><td>这次调用结束的时刻。<strong>可能缺席</strong>：还在跑，或者流被中止时兜底收尾不写这一个。</td></tr><tr><td><code>phase</code></td><td><code>ToolCallPhase</code></td><td></td><td>这次调用走到哪一步，默认 input-available。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>startTime</code></td><td><code>number</code></td><td></td><td>这次调用开始的时刻，毫秒时间戳。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ToolCallTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline 描边（缺省档）、subtle 底色分区、ghost 无壳内联。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>ToolCallOpenChangeDetails</code></td><td>开合变化；detail 为 <code>{ open: boolean, source: &#39;user&#39; | &#39;auto&#39; | &#39;api&#39; }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhToolCallRoot</code></td><td><code>default</code></td><td><code>ToolCallRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>label</code></td><td>props.phase</td></tr><tr><td><code>summary</code></td><td>props.phase</td></tr><tr><td><code>status</code></td><td>props.phase</td></tr><tr><td><code>duration</code></td><td>props.phase</td></tr><tr><td><code>approval</code></td><td>props.phase</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>input</code></td><td>props.phase</td></tr><tr><td><code>output</code></td><td>props.phase</td></tr><tr><td><code>error</code></td><td>props.phase</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>auto.collapsed</code> · <code>auto.expanded</code> · <code>held.collapsed</code> · <code>held.expanded</code></p><p><strong>事件</strong>：<code>TOGGLE</code> · <code>OPEN</code> · <code>CLOSE</code> · <code>PHASE.ACTIVE</code> · <code>PHASE.SETTLE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isAutoAllowed</code> · <code>isAutoEnabled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useToolCall</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>phase</code></td><td><code>ToolCallPhase</code></td><td></td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td>这一档算不算在跑。</td></tr><tr><td><code>settled</code></td><td><code>boolean</code></td><td>这一档算不算已经落定：跑完了，或者跑砸了。</td></tr><tr><td><code>errored</code></td><td><code>boolean</code></td><td>这一档算不算跑砸了。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>statusText</code></td><td><code>string</code></td><td>读屏用的一句话，由宿主写进会话级的那一个播报区。</td></tr><tr><td><code>durationMs</code></td><td><code>number | undefined</code></td><td>跑了多久，毫秒；两个时刻任一缺席即 undefined。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getStatusProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDurationProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getApprovalProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getInputProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getOutputProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getErrorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在折叠开关上且未禁用</td><td>展开或收起详情，并把自动开合永久停用</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-describedby</code></td><td><code>error</code> 部件的 id | undefined</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;region&#39;</td></tr></tbody></table><ul><li>开关带 <code>aria-expanded</code> 与 <code>aria-controls</code>，详情区是 <code>role=region</code> 且由开关命名。</li><li>出错时开关才补 <code>aria-describedby</code> 指向错误区——无条件挂会指向一个作者根本没渲的节点。</li><li>卡片自己不开活区：一屏若干张卡各开一个会互相打断。播报文本由 <code>statusText</code> 交出去， 由宿主写进会话级的那一个播报区。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tool-call.css</code> 按部件选择：<code>[data-scope=&quot;tool-call&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-errored</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-settled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>label</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>summary</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>status</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>duration</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>duration</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>approval</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>input</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>output</code></td><td><code>data-state</code></td><td>props.phase</td></tr><tr><td><code>error</code></td><td><code>data-state</code></td><td>props.phase</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tool-call-bg</code> · <code>--xh-tool-call-border</code> · <code>--xh-tool-call-border-error</code> · <code>--xh-tool-call-content-gap</code> · <code>--xh-tool-call-duration-fg</code> · <code>--xh-tool-call-error-fg</code> · <code>--xh-tool-call-font-size</code> · <code>--xh-tool-call-icon-size</code> · <code>--xh-tool-call-indicator-fg</code> · <code>--xh-tool-call-label-font</code> · <code>--xh-tool-call-px</code> · <code>--xh-tool-call-py</code> · <code>--xh-tool-call-radius</code> · <code>--xh-tool-call-shadow</code> · <code>--xh-tool-call-shimmer-duration</code> · <code>--xh-tool-call-status-bg-approval</code> · <code>--xh-tool-call-status-bg-done</code> · <code>--xh-tool-call-status-bg-error</code> · <code>--xh-tool-call-status-fg</code> · <code>--xh-tool-call-status-fg-approval</code> · <code>--xh-tool-call-status-fg-done</code> · <code>--xh-tool-call-status-fg-error</code> · <code>--xh-tool-call-status-font-size</code> · <code>--xh-tool-call-status-px</code> · <code>--xh-tool-call-status-py</code> · <code>--xh-tool-call-status-radius</code> · <code>--xh-tool-call-status-shimmer-base</code> · <code>--xh-tool-call-status-shimmer-sheen</code> · <code>--xh-tool-call-summary-bg</code> · <code>--xh-tool-call-summary-fg</code> · <code>--xh-tool-call-summary-font-size</code> · <code>--xh-tool-call-summary-px</code> · <code>--xh-tool-call-summary-radius</code> · <code>--xh-tool-call-tone-bar</code> · <code>--xh-tool-call-tone-fg</code> · <code>--xh-tool-call-trigger-bg-hover</code> · <code>--xh-tool-call-trigger-fg</code> · <code>--xh-tool-call-trigger-gap</code> · <code>--xh-tool-call-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-tool-call-collapse</code> · <code>xh-tool-call-enter</code> · <code>xh-tool-call-expand</code> · <code>xh-tool-call-shimmer</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>rotate</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>参数与结果用<a href="./code-view">代码视图</a>：参数在流式期是半截 JSON，把 <code>complete</code> 接成 「阶段不是参数在传」即可。富文本结果走<a href="./markdown-stream">流式正文</a>。</li><li>结果是代码改动时，详情那一格装<a href="./diff-view">差异视图</a>；收起态的摘要取它的 <code>stats</code> 折成 <code>+{added} −{removed} 文件名</code> 写进摘要位，减号用 U+2212 而不是连字符。 摘要要能悬停看全文就套<a href="./hover-card">悬浮卡</a>，别自己往 body 上挂节点。</li><li>审批那一格装<a href="./approval">审批</a>。</li><li>复制不内建，与<a href="./clipboard">剪贴板</a>组合；多张并排要方向键跳卡片就套<a href="./toolbar">工具条</a>。</li><li>一轮里跑了好几次工具时，外面套一层<a href="./accordion">手风琴</a>当分组： 手风琴的开关里写「跑了 N 个工具」，计数那一段加 <code>font-variant-numeric: tabular-nums</code> 免得数字跳动时左右挪；整组的开合由手风琴的 <code>aria-expanded</code> 承担，卡片各自只管自己那一张。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>工具名与状态都写在开关里：它们会自然构成开关的可访问名（「搜索，已完成」）。</li><li>出错态要容忍没有错误文本：流被中止时未拿到结果的调用会被收尾成出错，但拿不到原因。</li><li>摘要位只放一句能一眼读完的参数（查询词、文件路径），整个 JSON 留给详情里的代码视图。</li><li>耗时文案走 <code>translations.ranFor</code> 模板串，秒数由宿主现场代入；<code>endTime</code> 缺席时别渲染这一格。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每张卡各开一个 <code>aria-live</code>：一屏五张卡就是五个活区互相打断。</li><li>用禁用表达「还不能展开」：读屏用户连它存在都听不到。</li></ul>',51))])}const q=n(h,[["render",u]]);export{P as __pageData,q as default};
